import type { CreateHost, Host, JobView, Outcome } from '../host.ts';

type Status = JobView['status'];
interface Job { status: Status; tries: number; maxTries: number }

const ok = (): Outcome => ({ ok: true });
const no = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async () => {
  const jobs = new Map<string, Job>();

  // A failed or lost try: retry if tries remain, else fail; a cancelling job is cancelled.
  const endTry = (id: string): Outcome => {
    const j = jobs.get(id);
    if (!j) return no('unknown job');
    if (j.status === 'cancelling') { j.status = 'cancelled'; return ok(); }
    if (j.status !== 'running') return no(`job is ${j.status}`);
    j.status = j.tries < j.maxTries ? 'queued' : 'failed';
    return ok();
  };

  const host: Host = {
    async submit(id, maxTries) {
      if (!Number.isInteger(maxTries) || maxTries < 1 || maxTries > 3) return no('maxTries must be 1 to 3');
      if (jobs.has(id)) return no('job exists');
      jobs.set(id, { status: 'queued', tries: 0, maxTries });
      return ok();
    },
    async claim(id) {
      const j = jobs.get(id);
      if (!j) return no('unknown job');
      if (j.status !== 'queued') return no(`job is ${j.status}`);
      if (j.tries >= j.maxTries) return no('no tries left');
      j.status = 'running';
      j.tries += 1;
      return ok();
    },
    async succeed(id) {
      const j = jobs.get(id);
      if (!j) return no('unknown job');
      if (j.status !== 'running' && j.status !== 'cancelling') return no(`job is ${j.status}`);
      j.status = 'succeeded';
      return ok();
    },
    async fail(id) { return endTry(id); },
    async lost(id) { return endTry(id); },
    async cancel(id) {
      const j = jobs.get(id);
      if (!j) return no('unknown job');
      if (j.status === 'queued') j.status = 'cancelled';
      else if (j.status === 'running') j.status = 'cancelling';
      else return no(`job is ${j.status}`);
      return ok();
    },
    async job(id) {
      const j = jobs.get(id);
      return j ? { ...j } : null;
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('retries then fails', async () => {
  const h = await createHost();
  assert.equal((await h.submit('a', 0)).ok, false);
  assert.equal((await h.submit('a', 4)).ok, false);
  assert.deepEqual(await h.submit('a', 2), { ok: true });
  assert.equal((await h.submit('a', 2)).ok, false);
  assert.equal((await h.succeed('a')).ok, false);
  await h.claim('a'); await h.fail('a');
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('a'); await h.lost('a');
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, false);
  assert.equal(await h.job('zz'), null);
  assert.equal((await h.cancel('zz')).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.submit('a', 1); await h.cancel('a');
  assert.equal((await h.job('a'))!.status, 'cancelled');
  assert.equal((await h.cancel('a')).ok, false);
  await h.submit('b', 1); await h.claim('b'); await h.cancel('b');
  assert.equal((await h.job('b'))!.status, 'cancelling');
  assert.equal((await h.claim('b')).ok, false);
  assert.equal((await h.cancel('b')).ok, false);
  await h.succeed('b');
  assert.equal((await h.job('b'))!.status, 'succeeded');
  await h.submit('c', 3); await h.claim('c'); await h.cancel('c'); await h.lost('c');
  assert.deepEqual(await h.job('c'), { status: 'cancelled', tries: 1, maxTries: 3 });
});
