30	// Re-export the shared loader (eval scripts and older callers import it from
31	// here). ONE loader for the whole pipeline lives in load-spec.mjs.
32	export { loadSpec };
33	
34	// ── Build the (action, data) domain from the contract + observed traces ────
35	// dataDomain in the contract wins; otherwise values are inferred from the trace
36	// corpus; an action with no data fields contributes a single {} step.
37	//
38	// NOT the checker's exploration domain — that comes from the module's own
39	// manifest() (sam-adapter.domainFromManifest). This is the CONTRACT-side view,
40	// used to report declared-but-unenumerable actions (polygen's domain-gap
41	// notes, polynv's grade).
42	export function buildDomain(contract, windows = []) {
43	  const actions = Object.keys(contract.actions || {});
44	  const observed = {}; // action -> field -> Set(values)
45	  for (const w of windows) {
46	    const d = w.data || {};
47	    observed[w.action] = observed[w.action] || {};
48	    for (const [k, val] of Object.entries(d)) {
49	      // stable(): key-order-insensitive dedup (trace data is JSON-clean, so
50	      // stable output parses back with JSON.parse below).
51	      (observed[w.action][k] = observed[w.action][k] || new Set()).add(stable(val));
52	    }
53	  }
54	  const steps = []; // { action, data }
55	  const notes = [];
56	  for (const action of actions) {
57	    // dataFieldsOf: the SAME accessor build_prompt uses, so a contract written
58	    // with `data:` instead of `dataFields:` gets the same fields in the
59	    // explored domain as in the generation prompt.
60	    const fields = Object.keys(dataFieldsOf(contract.actions[action]));
61	    if (fields.length === 0) { steps.push({ action, data: {} }); continue; }
62	    const perField = fields.map((f) => {
63	      const fromContract = contract.dataDomain?.[action]?.[f];
64	      if (Array.isArray(fromContract)) return fromContract;
65	      const inferred = observed[action]?.[f];
66	      if (inferred && inferred.size) return [...inferred].map((s) => JSON.parse(s));
67	      notes.push(`no domain for ${action}.${f} (no contract dataDomain, none in traces) — skipped`);
68	      return [];
69	    });
70	    if (perField.some((vals) => vals.length === 0)) continue; // can't enumerate this action
71	    // cartesian product over the fields
72	    let combos = [{}];
73	    fields.forEach((f, i) => {
74	      const next = [];
75	      for (const c of combos) for (const v of perField[i]) next.push({ ...c, [f]: v });
76	      combos = next;
77	    });
78	    for (const data of combos) steps.push({ action, data });
79	  }
80	  return { steps, notes };
81	}
82	
83	/**
84	 * Explore the reachable state graph of a spec and check invariants. The spec
85	 * is a v2 SAM strict-profile module ({instance, init, actions, getState,
86	 * setState}), driven through scripts/sam-adapter.cjs with manifest() domains
