'use strict';

// SAM v2 strict-profile spec of src/host.impl.ts: the job table, over two job ids.
const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

// jobs: { [id]: { status, tries, maxTries } }; an absent id was never submitted.
const INITIAL_STATE = { jobs: {} };

const JOB_DOMAIN = [{ job: 'a' }, { job: 'b' }];
const jobSchema = { job: { type: 'string' } };
const intent = (domain = JOB_DOMAIN, schema = jobSchema) =>
  ({ action: (data = {}) => ({ ...data }), schema, domain });

const SUBMIT_DOMAIN = [];
for (const job of ['a', 'b']) for (const maxTries of [0, 1, 2, 3, 4]) SUBMIT_DOMAIN.push({ job, maxTries });

const put = (model, next, id, job) => { next.jobs = { ...model.jobs, [id]: job }; };

// fail and lost: retry if tries remain, else failed; a cancelling job is cancelled.
const endTry = (model) => (p, { reject, next }) => {
  const j = model.jobs[p.job];
  if (!j) return reject('unknown-job');
  if (j.status === 'cancelling') return put(model, next, p.job, { ...j, status: 'cancelled' });
  if (j.status !== 'running') return reject('not-running');
  put(model, next, p.job, { ...j, status: j.tries < j.maxTries ? 'queued' : 'failed' });
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: { jobs: { type: 'object' } },
    actions: {
      SUBMIT: intent(SUBMIT_DOMAIN, { job: { type: 'string' }, maxTries: { type: 'number' } }),
      CLAIM: intent(),
      SUCCEED: intent(),
      FAIL: intent(),
      LOST: intent(),
      CANCEL: intent(),
    },
    acceptors: {
      SUBMIT: (model) => (p, { reject, next }) => {
        if (!Number.isInteger(p.maxTries) || p.maxTries < 1 || p.maxTries > 3) return reject('bad-max-tries');
        if (model.jobs[p.job]) return reject('job-exists');
        put(model, next, p.job, { status: 'queued', tries: 0, maxTries: p.maxTries });
      },
      CLAIM: (model) => (p, { reject, next }) => {
        const j = model.jobs[p.job];
        if (!j) return reject('unknown-job');
        if (j.status !== 'queued') return reject('not-queued');
        if (j.tries >= j.maxTries) return reject('no-tries-left');
        put(model, next, p.job, { ...j, status: 'running', tries: j.tries + 1 });
      },
      SUCCEED: (model) => (p, { reject, next }) => {
        const j = model.jobs[p.job];
        if (!j) return reject('unknown-job');
        if (j.status !== 'running' && j.status !== 'cancelling') return reject('not-running');
        put(model, next, p.job, { ...j, status: 'succeeded' });
      },
      FAIL: endTry,
      LOST: endTry,
      CANCEL: (model) => (p, { reject, next }) => {
        const j = model.jobs[p.job];
        if (!j) return reject('unknown-job');
        if (j.status === 'queued') return put(model, next, p.job, { ...j, status: 'cancelled' });
        if (j.status === 'running') return put(model, next, p.job, { ...j, status: 'cancelling' });
        return reject('not-cancellable');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  SUBMIT: (data = {}) => intents.SUBMIT(data),
  CLAIM: (data = {}) => intents.CLAIM(data),
  SUCCEED: (data = {}) => intents.SUCCEED(data),
  FAIL: (data = {}) => intents.FAIL(data),
  LOST: (data = {}) => intents.LOST(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

