// Drives src/host.impl.ts through random walks and writes polygraph trace windows
// (one NDJSON file per walk) to spec/traces/. Run: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, JobView } from '../host.ts';

const IDS = ['a', 'b'];
const ACTIONS = ['SUBMIT', 'CLAIM', 'SUCCEED', 'FAIL', 'LOST', 'CANCEL'] as const;

async function snapshot(h: Host) {
  const jobs: Record<string, JobView> = {};
  for (const id of IDS) { const j = await h.job(id); if (j) jobs[id] = j; }
  return { jobs };
}

let seed = 12345;
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

for (let walk = 0; walk < 60; walk++) {
  const h = await createHost();
  const lines: string[] = [];
  for (let step = 0; step < 25; step++) {
    const action = ACTIONS[rand(ACTIONS.length)];
    const job = IDS[rand(IDS.length)];
    const data: Record<string, unknown> = { job };
    const pre = await snapshot(h);
    if (action === 'SUBMIT') { data.maxTries = rand(5); await h.submit(job, data.maxTries as number); }
    else await h[action.toLowerCase() as 'claim'](job);
    lines.push(JSON.stringify({ pre, action, data, post: await snapshot(h) }));
  }
  writeFileSync(new URL(`walk-${walk}.ndjson`, dir), lines.join('\n') + '\n');
}

