      j.tries += 1;
      return ok();
    },
    async succeed(id) {
      const j = jobs.get(id);
      if (!j) return no('unknown job');
      if (j.status !== 'running' && j.status !== 'cancelling') return no(`job is ${j.status}`);
      j.status = 'succeeded';
      return ok();
    },
    async fail(id) { return endTry(id); },
    async lost(id) { return endTry(id); },
    async cancel(id) {
      const j = jobs.get(id);
      if (!j) return no('unknown job');
      if (j.status === 'queued') j.status = 'cancelled';
      else if (j.status === 'running') j.status = 'cancelling';
      else return no(`job is ${j.status}`);
      return ok();
    },
    async job(id) {
      const j = jobs.get(id);
      return j ? { ...j } : null;
    },
  };
  return host;
};

