// Rules the brief requires, over the jobs table.
const STATUSES = ['queued', 'running', 'cancelling', 'succeeded', 'failed', 'cancelled', 'held'];
const TERMINAL = ['succeeded', 'failed', 'cancelled'];
const all = (s) => Object.values(s.jobs);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export const stateInvariants = [
  { name: 'valid-status', pred: (s) => all(s).every((j) => STATUSES.includes(j.status)) },
  { name: 'max-tries-1-to-3', pred: (s) => all(s).every((j) => [1, 2, 3].includes(j.maxTries)) },
  { name: 'never-tried-beyond-limit', pred: (s) => all(s).every((j) => j.tries >= 0 && j.tries <= j.maxTries) },
  { name: 'failed-only-after-a-try', pred: (s) => all(s).every((j) => j.status !== 'failed' || j.tries >= 1) },
  { name: 'queued-or-held-has-a-try-left', pred: (s) => all(s).every((j) => !['queued', 'held'].includes(j.status) || j.tries < j.maxTries) },
  { name: 'running-was-tried', pred: (s) => all(s).every((j) => !['running', 'cancelling'].includes(j.status) || j.tries >= 1) },
];

export const transitionInvariants = [
  {
    name: 'unknown-job-refused',
    pred: (pre, action, data, post) => action === 'SUBMIT' || pre.jobs[data.job] !== undefined || same(pre, post),
  },
  {
    name: 'jobs-never-disappear-or-change-limit',
    pred: (pre, _a, _d, post) => Object.entries(pre.jobs).every(([id, j]) => post.jobs[id] && post.jobs[id].maxTries === j.maxTries),
  },
  {
    name: 'only-the-named-job-changes',
    pred: (pre, _a, data, post) => Object.keys({ ...pre.jobs, ...post.jobs })
      .every((id) => id === data.job || same(pre.jobs[id], post.jobs[id])),
  },
  {
    name: 'terminal-is-final',
    pred: (pre, _a, data, post) => !pre.jobs[data.job] || !TERMINAL.includes(pre.jobs[data.job].status) || same(pre, post),
  },
  {
    name: 'tries-only-counted-by-claim',
    pred: (pre, action, data, post) => {
      const a = pre.jobs[data.job], b = post.jobs[data.job];
      if (!a || !b) return true;
      const claimed = action === 'CLAIM' && a.status === 'queued' && b.status === 'running';
      return claimed ? b.tries === a.tries + 1 : b.tries === a.tries;
    },
  },
  {
    name: 'cancel-keeps-done-work',
    pred: (pre, action, data, post) => {
      const a = pre.jobs[data.job];
      if (!a || a.status !== 'cancelling') return true;
      const s = post.jobs[data.job].status;
      if (action === 'SUCCEED') return s === 'succeeded';
      if (['FAIL', 'LOST', 'FAIL_PERMANENTLY'].includes(action)) return s === 'cancelled';
      return s === 'cancelling';
    },
  },
  {
    name: 'running-try-ends-as-the-brief-says',
    pred: (pre, action, data, post) => {
      const a = pre.jobs[data.job];
      if (!a || a.status !== 'running') return true;
      const s = post.jobs[data.job].status;
      if (action === 'FAIL_PERMANENTLY') return s === 'failed';
      if (action === 'FAIL' || action === 'LOST') return s === (a.tries < a.maxTries ? 'queued' : 'failed');
      return true;
    },
  },
  {
    name: 'failed-only-from-running',
    pred: (pre, _a, data, post) => {
      const a = pre.jobs[data.job], b = post.jobs[data.job];
      return !b || b.status !== 'failed' || (a && ['running', 'failed'].includes(a.status));
    },
  },
  {
    name: 'held-only-by-hold-of-queued',
    pred: (pre, action, data, post) => {
      const a = pre.jobs[data.job], b = post.jobs[data.job];
      if (!b || b.status !== 'held' || (a && a.status === 'held')) return true;
      return action === 'HOLD' && a.status === 'queued';
    },
  },
  {
    name: 'held-job-leaves-only-by-release-or-cancel',
    pred: (pre, action, data, post) => {
      const a = pre.jobs[data.job];
      if (!a || a.status !== 'held') return true;
      const s = post.jobs[data.job].status;
      if (action === 'RELEASE') return s === 'queued';
      if (action === 'CANCEL') return s === 'cancelled';
      return same(pre, post);
    },
  },
];

